          <div className="w-full flex md:justify-between overflow-x-auto no-scrollbar gap-4 md:gap-0 px-2 py-4">
            {PROCESS_STEPS.map((step, index) => (
              <button
                key={index}
                onClick={() => setActiveStep(index)}
                className={`relative z-10 flex-shrink-0 flex flex-col items-center gap-2 group focus:outline-none transition-all duration-300 ${
                  activeStep === index ? 'scale-110' : 'opacity-60 hover:opacity-100'
