                  {step.number}
                </div>
                <span className={`text-xs md:text-sm font-medium whitespace-nowrap ${
                  activeStep === index ? 'text-indigo-400' : 'text-slate-500'
                }`}>
                  {step.title}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Active Step Content Card */}
