import React, { useState } from 'react';
import { ArrowLeft, ArrowRight, Maximize2 } from 'lucide-react';
import { PROCESS_STEPS } from '../constants';
import ImageViewer from './ImageViewer';

const Process: React.FC = () => {
  const [activeStep, setActiveStep] = useState(0);
  const [isViewerOpen, setIsViewerOpen] = useState(false);

  const handleNext = () => {
    setActiveStep((prev) => (prev + 1) % PROCESS_STEPS.length);
  };

  const handlePrev = () => {
    setActiveStep((prev) => (prev - 1 + PROCESS_STEPS.length) % PROCESS_STEPS.length);
  };

  return (
    <section id="process" className="py-24 bg-transparent overflow-hidden relative">
      <ImageViewer 
        isOpen={isViewerOpen} 
        onClose={() => setIsViewerOpen(false)} 
        src={PROCESS_STEPS[activeStep].imageUrl || ''} 
        alt={PROCESS_STEPS[activeStep].title} 
      />

      {/* Background decoration */}
      <div className="absolute left-0 top-0 w-64 h-64 bg-indigo-600/5 blur-[100px] rounded-full pointer-events-none" />
      <div className="absolute right-0 bottom-0 w-64 h-64 bg-purple-600/5 blur-[100px] rounded-full pointer-events-none" />

      <div className="container mx-auto px-6 relative z-10">
        <div className="mb-8">
          <h2 className="text-3xl md:text-5xl font-bold text-white mb-6">Процесс работы</h2>
          <p className="text-slate-400 text-lg max-w-2xl border-l-2 border-indigo-500 pl-4">
            Прозрачные этапы от идеи до релиза.
          </p>
        </div>

        {/* Timeline Navigation */}
        <div className="flex items-start justify-between mb-8 relative">
          {/* Connector Line - Aligned to circle centers */}
          <div className="absolute top-[72px] md:top-[80px] left-0 w-full h-0.5 bg-slate-800/50 z-0 hidden md:block" />

          {/* Increased to py-12 (48px) to allow room for scale-110 and shadow */}
          <div className="w-full flex md:justify-between overflow-x-auto no-scrollbar gap-4 md:gap-0 px-4 py-12">
            {PROCESS_STEPS.map((step, index) => (
              <button
                key={index}
                onClick={() => setActiveStep(index)}
                style={{ WebkitTapHighlightColor: 'transparent' }}
                className={`relative z-10 flex-shrink-0 flex flex-col items-center gap-4 group focus:outline-none outline-none ring-0 transition-all duration-300 cursor-pointer ${
                  activeStep === index ? 'opacity-100' : 'opacity-50 hover:opacity-80'
                }`}
              >
                <div 
                  className={`w-12 h-12 md:w-16 md:h-16 rounded-full flex items-center justify-center text-lg md:text-xl font-bold border-4 transition-all duration-300 box-content ${
                    activeStep === index 
                      ? 'bg-slate-900 border-indigo-500 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.5)] scale-110' 
                      : activeStep > index
                        ? 'bg-slate-900 border-indigo-500/30 text-indigo-400/50'
                        : 'bg-slate-900 border-slate-800 text-slate-600'
                  }`}
                >
                  {step.number}
                </div>
                <span className={`text-xs md:text-sm font-medium whitespace-nowrap px-2 py-1 rounded-md transition-colors ${
                  activeStep === index ? 'text-white bg-indigo-500/10' : 'text-slate-500'
                }`}>
                  {step.title}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Active Step Content Card */}
        <div className="relative">
             <div className="bg-slate-900 rounded-3xl border border-slate-800 p-6 md:p-12 overflow-hidden shadow-2xl relative min-h-[400px] flex flex-col justify-center">
                 {/* Content Grid */}
                 <div className="grid md:grid-cols-2 gap-8 md:gap-12 items-center">
                    {/* Text */}
                    <div className="order-2 md:order-1 space-y-6 animate-fade-in flex flex-col justify-center">
                       <div className="inline-flex items-center gap-2 text-indigo-400 font-mono text-sm">
                           <span>STEP {PROCESS_STEPS[activeStep].number}</span>
                           <div className="h-px w-8 bg-indigo-500/50" />
                       </div>
                       <h3 className="text-3xl md:text-4xl font-bold text-white">
                         {PROCESS_STEPS[activeStep].title}
                       </h3>
                       {/* Min height prevents jumping buttons when text length changes */}
                       <p className="text-slate-400 text-lg leading-relaxed min-h-[8rem]">
                         {PROCESS_STEPS[activeStep].description}
                       </p>

                       {/* Navigation Buttons */}
                       <div className="flex gap-4 pt-6">
                           <button 
                             onClick={handlePrev}
                             className="p-3 rounded-full border border-slate-700 text-slate-400 hover:text-white hover:bg-slate-800 transition-all focus:outline-none outline-none ring-0"
                             aria-label="Previous step"
                           >
                             <ArrowLeft size={24} />
                           </button>
                           <button 
                             onClick={handleNext}
                             className="p-3 rounded-full bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg shadow-indigo-500/20 transition-all focus:outline-none outline-none ring-0"
                             aria-label="Next step"
                           >
                             <ArrowRight size={24} />
                           </button>
                       </div>
                    </div>

                    {/* Image */}
                    <div 
                      className="order-1 md:order-2 relative aspect-video md:aspect-square rounded-2xl overflow-hidden bg-slate-800 shadow-xl group cursor-pointer"
                      onClick={() => setIsViewerOpen(true)}
                    >
                       <div className="absolute inset-0 bg-indigo-500/10 mix-blend-overlay z-10 pointer-events-none" />
                       <img 
                         key={activeStep} // Force re-render for simple animation
                         src={PROCESS_STEPS[activeStep].imageUrl} 
                         alt={PROCESS_STEPS[activeStep].title} 
                         className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105 animate-fade-in"
                       />
                       <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-20">
                          <div className="bg-slate-900/80 p-3 rounded-full backdrop-blur-sm text-white">
                            <Maximize2 size={24} />
                          </div>
                        </div>
                    </div>
                 </div>
             </div>
        </div>
      </div>
    </section>
  );
};

