import React, { useState, useEffect } from 'react';
import { ExternalLink, Maximize2, ArrowLeft, ArrowRight, Construction } from 'lucide-react';
import { PROJECTS } from '../constants';
import ImageViewer from './ImageViewer';

const Portfolio: React.FC = () => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isAnimating, setIsAnimating] = useState(false);

  const nextSlide = () => {
    if (isAnimating) return;
    setIsAnimating(true);
    setCurrentIndex((prev) => (prev + 1) % PROJECTS.length);
  };

  const prevSlide = () => {
    if (isAnimating) return;
    setIsAnimating(true);
    setCurrentIndex((prev) => (prev - 1 + PROJECTS.length) % PROJECTS.length);
  };

  useEffect(() => {
    const timer = setTimeout(() => setIsAnimating(false), 500);
    return () => clearTimeout(timer);
  }, [currentIndex]);

  const currentProject = PROJECTS[currentIndex];

  return (
    <section id="portfolio" className="py-24 bg-transparent overflow-hidden relative">
      <ImageViewer 
        isOpen={!!selectedImage} 
        onClose={() => setSelectedImage(null)} 
        src={selectedImage || ''} 
        alt="Project screenshot" 
      />

      <div className="container mx-auto px-6 relative z-10">
        <div className="flex flex-col md:flex-row md:items-end justify-between mb-12 gap-6">
          <div>
            <h2 className="text-3xl md:text-5xl font-bold text-white mb-4">Избранные проекты</h2>
            <p className="text-slate-400 text-lg max-w-2xl">
              Реальные кейсы внедрения AI и автоматизации в бизнес-процессы.
            </p>
          </div>

          {/* Navigation Controls */}
          <div className="flex gap-4">
            <button 
              onClick={prevSlide}
              className="p-4 rounded-full border border-slate-700 text-slate-400 hover:text-white hover:bg-slate-800 transition-all focus:outline-none"
              aria-label="Previous project"
            >
              <ArrowLeft size={24} />
            </button>
            <button 
              onClick={nextSlide}
              className="p-4 rounded-full bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg shadow-indigo-500/20 transition-all focus:outline-none"
              aria-label="Next project"
            >
              <ArrowRight size={24} />
            </button>
          </div>
        </div>

        {/* Carousel Content */}
        <div className="relative group">
           {/* Glow Effect based on current slide */}
           <div className="absolute inset-0 bg-indigo-600/20 blur-[100px] rounded-[3rem] transition-all duration-700 pointer-events-none" />

           <div 
             key={currentIndex}
             className="relative bg-slate-900/80 backdrop-blur-xl border border-slate-800 rounded-[2rem] overflow-hidden shadow-2xl animate-fade-in"
           >
             <div className="grid lg:grid-cols-5 gap-0">

               {/* Image Section (3/5 width on desktop) */}
               <div className="lg:col-span-3 relative aspect-video lg:aspect-auto overflow-hidden bg-slate-800 cursor-pointer min-h-[300px] lg:min-h-[500px]" onClick={() => setSelectedImage(currentProject.imageUrl)}>
                 <img 
                   src={currentProject.imageUrl} 
                   alt={currentProject.title} 
                   className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                 />
                 <div className="absolute inset-0 bg-gradient-to-t from-slate-900/80 via-transparent to-transparent opacity-60 pointer-events-none" />

                 {/* View Icon Overlay */}
                 <div className="absolute inset-0 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity duration-300 pointer-events-none">
                    <div className="bg-slate-900/80 p-4 rounded-full backdrop-blur-sm text-white border border-slate-700">
                      <Maximize2 size={32} />
                    </div>
                 </div>
               </div>

               {/* Info Section (2/5 width on desktop) */}
               <div className="lg:col-span-2 p-8 md:p-12 flex flex-col justify-center border-t lg:border-t-0 lg:border-l border-slate-800 bg-slate-900/50">
                 <div className="flex flex-wrap gap-2 mb-6">
                   {currentProject.tags.map((tag) => (
                     <span key={tag} className="text-xs font-bold tracking-wide uppercase px-3 py-1.5 rounded-md bg-indigo-500/10 text-indigo-300 border border-indigo-500/20">
                       {tag}
                     </span>
                   ))}
                 </div>

                 <h3 className="text-3xl md:text-4xl font-bold text-white mb-6 leading-tight">
                   {currentProject.title}
                 </h3>

                 <p className="text-slate-400 text-lg leading-relaxed mb-10">
                   {currentProject.description}
                 </p>

                 <div className="mt-auto">
                    {currentProject.link ? (
                      <a 
                       href={currentProject.link} 
                       target="_blank" 
                       rel="noopener noreferrer"
                       className="inline-flex items-center gap-3 px-8 py-4 bg-white text-slate-900 hover:bg-indigo-50 rounded-xl font-bold transition-all transform hover:-translate-y-1 shadow-lg shadow-white/5"
                     >
                       <span>Смотреть кейс</span>
                       <ExternalLink size={20} />
                     </a>
                    ) : (
                      <button 
                        disabled
                        className="inline-flex items-center gap-3 px-8 py-4 bg-slate-800 text-slate-500 rounded-xl font-medium border border-slate-700 cursor-not-allowed opacity-75"
                      >
                        <Construction size={20} />
                        <span>В разработке</span>
                      </button>
                    )}
                 </div>
               </div>
             </div>
           </div>
        </div>

        {/* Dots Pagination */}
        <div className="flex justify-center gap-3 mt-8">
          {PROJECTS.map((_, index) => (
            <button
              key={index}
              onClick={() => {
                if (!isAnimating) {
                  setIsAnimating(true);
                  setCurrentIndex(index);
                }
              }}
              className={`h-2 rounded-full transition-all duration-300 ${
                index === currentIndex 
                  ? 'w-10 bg-indigo-500' 
                  : 'w-2 bg-slate-700 hover:bg-slate-600'
              }`}
              aria-label={`Go to project ${index + 1}`}
            />
          ))}
        </div>
      </div>
    </section>
  );
};

