                   className="absolute inset-0 bg-cover bg-center blur-xl opacity-40 scale-110"
                   style={{ backgroundImage: `url(${currentProject.imageUrl})` }}
                 />

                 <img 
                   src={currentProject.imageUrl} 
                   alt={currentProject.title} 
