- Для банков/HR: AI-Банк, Mira AI (рекрутер).
- Для недвижимости: Rent Pilot AI (CRM с голосовым вводом).
- Для продаж: IT Sales AI (тренажеры звонков).
`;

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
}

const AiAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'init', 
      role: 'assistant', 
      content: 'Привет! Я AI-помощник Алекса. Могу рассказать про наши проекты или сориентировать по стоимости. \n\nСкажите, какую бизнес-задачу вы хотите решить с помощью AI?' 
    }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSessionRef = useRef<Chat | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  // Функция скролла к контактам
  const handleScrollToContact = () => {
    const element = document.getElementById('contact');
    if (element) {
      setIsOpen(false); // Закрываем чат, чтобы не мешал
      const headerOffset = 100;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.scrollY - headerOffset;
      window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue.trim()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsLoading(true);

    try {
      let assistantContent = "";
      // Используем ключ из переменных окружения, как того требует инструкция для @google/genai
      const apiKey = process.env.API_KEY; 

      if (apiKey) {
        // Инициализация чата, если еще не создана
        if (!chatSessionRef.current) {
           const ai = new GoogleGenAI({ apiKey });
           chatSessionRef.current = ai.chats.create({
             model: 'gemini-3-flash-preview',
             config: {
               systemInstruction: SYSTEM_PROMPT,
             }
           });
        }

        const response = await chatSessionRef.current.sendMessage({
           message: userMessage.content
        });

        assistantContent = response.text || "Извините, не удалось сгенерировать ответ.";

      } else {
        // --- ДЕМО РЕЖИМ (Если нет ключа) ---
        await new Promise(resolve => setTimeout(resolve, 1500)); // Имитация задержки
        const lowerInput = userMessage.content.toLowerCase();

        // Более сложная логика для демо-режима, чтобы соответствовать промпту
        if (lowerInput.includes('цен') || lowerInput.includes('стоит') || lowerInput.includes('бюджет')) {
          assistantContent = "Стоимость сильно зависит от функционала. Например, простой бот-консультант стоит от **150 000 ₽**, а сложная CRM-система — от **300 000 ₽**.\n\nУ вас уже есть готовое Техническое Задание (ТЗ) или пока только общая идея? [DEMO]";
        } else if (lowerInput.includes('идея') || lowerInput.includes('нет тз')) {
          assistantContent = "Понял, это нормально. Мы можем начать с обсуждения идеи и составления концепции (Этап 01).\n\nРасскажите в двух словах, что именно должно делать приложение? Это для внутренних нужд компании или для клиентов? [DEMO]";
        } else if (lowerInput.includes('заказ') || lowerInput.includes('связ') || lowerInput.includes('контакт') || lowerInput.includes('готов') || lowerInput.includes('да')) {
          assistantContent = "Отлично! Тогда давайте перейдем к делу. Заполните короткую форму ниже, и Алекс свяжется с вами для детального обсуждения. [ACTION:SCROLL_TO_CONTACT]";
        } else {
          assistantContent = "Интересная задача. Мы работали с похожими кейсами. Например, **AI News Nexus** или **Rent Pilot**.\n\nКакой функционал для вас критически важен в первую очередь? [DEMO]";
        }
      }

      // Обработка Action Tag
      let finalContent = assistantContent;
      let shouldScroll = false;

      if (assistantContent.includes('[ACTION:SCROLL_TO_CONTACT]')) {
        finalContent = assistantContent.replace('[ACTION:SCROLL_TO_CONTACT]', '').trim();
        shouldScroll = true;
      }

      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: finalContent
      };

      setMessages(prev => [...prev, aiMessage]);

      if (shouldScroll) {
        setTimeout(handleScrollToContact, 2000); // Чуть большая задержка, чтобы успеть прочитать "Ок, переходим к форме"
      }

    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'assistant',
        content: "Произошла ошибка соединения с Gemini API. Попробуйте позже."
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Trigger Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed bottom-6 right-6 z-[60] p-4 rounded-full shadow-[0_0_30px_rgba(99,102,241,0.5)] transition-all duration-300 hover:scale-110 active:scale-95 flex items-center justify-center ${
          isOpen ? 'bg-slate-800 text-white rotate-90' : 'bg-gradient-to-r from-indigo-600 to-purple-600 text-white'
        }`}
      >
        {isOpen ? <X size={28} /> : <MessageCircle size={28} />}

        {/* Notification Dot if closed */}
        {!isOpen && (
           <span className="absolute -top-1 -right-1 flex h-4 w-4">
             <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
             <span className="relative inline-flex rounded-full h-4 w-4 bg-green-500"></span>
           </span>
        )}
      </button>

      {/* Chat Window */}
      <div 
        className={`fixed bottom-24 right-6 w-[90vw] md:w-[400px] h-[500px] max-h-[70vh] bg-slate-900/95 backdrop-blur-xl border border-indigo-500/30 rounded-2xl shadow-2xl flex flex-col z-[60] transition-all duration-300 origin-bottom-right ${
          isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-95 translate-y-10 pointer-events-none'
        }`}
      >
        {/* Header */}
        <div className="p-4 border-b border-slate-800 bg-gradient-to-r from-slate-900 to-slate-800 rounded-t-2xl flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-indigo-600/20 border border-indigo-500/50 flex items-center justify-center text-indigo-400 shadow-[0_0_15px_rgba(99,102,241,0.2)]">
              <Bot size={24} />
            </div>
            <div>
              <h3 className="font-bold text-white flex items-center gap-2">
                AI Partner
                <Sparkles size={14} className="text-yellow-400 animate-pulse" />
              </h3>
              <p className="text-xs text-green-400 font-medium flex items-center gap-1">
                <span className="w-1.5 h-1.5 bg-green-500 rounded-full"></span>
                Gemini 2.5
              </p>
            </div>
          </div>
          <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white">
            <ChevronDown size={20} />
          </button>
        </div>

        {/* Messages Body */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
          {messages.map((msg) => (
            <div 
              key={msg.id} 
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div 
                className={`max-w-[85%] p-3.5 rounded-2xl text-sm leading-relaxed ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-tr-none shadow-lg' 
                    : 'bg-slate-800 border border-slate-700 text-slate-200 rounded-tl-none shadow-md'
                }`}
              >
                <ReactMarkdown
                  components={{
                    ul: ({node, ...props}) => <ul className="list-disc ml-4 mb-2 space-y-1" {...props} />,
                    ol: ({node, ...props}) => <ol className="list-decimal ml-4 mb-2 space-y-1" {...props} />,
                    li: ({node, ...props}) => <li className="" {...props} />,
                    p: ({node, ...props}) => <p className="mb-2 last:mb-0" {...props} />,
                    strong: ({node, ...props}) => <span className="font-bold text-white" {...props} />,
                    a: ({node, ...props}) => <a className="text-indigo-300 underline hover:text-white" target="_blank" rel="noopener noreferrer" {...props} />,
                    h1: ({node, ...props}) => <h3 className="font-bold text-white text-base mb-2" {...props} />,
                    h2: ({node, ...props}) => <h4 className="font-bold text-white text-sm mb-2" {...props} />,
                    h3: ({node, ...props}) => <strong className="font-bold text-white block mb-1" {...props} />,
                  }}
                >
                  {msg.content}
                </ReactMarkdown>
              </div>
            </div>
          ))}

          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-slate-800 border border-slate-700 p-3 rounded-2xl rounded-tl-none flex gap-1.5 items-center">
                <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
