      let finalContent = assistantContent;
      let shouldScroll = false;

      if (assistantContent.includes('[ACTION:SCROLL_TO_CONTACT]')) {
        finalContent = assistantContent.replace('[ACTION:SCROLL_TO_CONTACT]', '').trim();
